// intent: Exercises write_bson_nested_head and iterative binary writer helpers by serializing a deeply nested structured object with custom keys to BSON.
#include <nlohmann/json.hpp>
#include <map>
#include <string>
#include <iostream>

struct simple_key {
    std::string s;
    bool operator<(const simple_key& o) const { return s < o.s; }
    operator std::string() const { return s;
 }
};

template <class Key, class Value>
using simple_map = std::map<Key, Value, std::less<Key>>;
using simple_json = nlohmann::basic_json<simple_map>;

int main() {
    try {
        simple_json j;
        simple_json inner;
        inner.emplace(simple_key{"inner"}, simple_json(99));
        j.emplace(simple_key{"outer"}, inner);
        auto bson = simple_json::to_bson(j);
        std::cout << "BSON size: " << bson.size() << std::endl;
    } catch (const std::exception& e) {
        std::cout << "Exception: " << e.what() << std::endl;
    }
    return 0;
}
